{
  "description": "The creature is a large quadrupedal mammal shown in right-facing profile against a plain off-white background, with the overall body shape, fur, and proportions of a brown bear. It is covered in dense, shaggy brown fur that is darker on the back and legs and lighter cream-white on the underbelly, chest and throat. Four sturdy, fur-covered legs support the body and end in broad clawed paws. Fused into the fur across the back, sides, neck, throat and leg joints are multiple glossy, dark reddish-brown to black chitinous plates resembling a beetle's exoskeleton, including a large curved horn on the forehead, a shield-like plate over the shoulders, and large ridged wing-cover plates on the flanks. A short furry tail is visible at the rear and the head is bear-like with a dark muzzle and nose.",
  "parts": [
    {
      "part": "head",
      "looks_like": "bear-like head with dense brown fur, a paler tan muzzle, a large black nose at the tip, a small dark brown eye, and a closed mouth",
      "where": "at the front right end of the body, facing to the right in profile"
    },
    {
      "part": "horns",
      "looks_like": "single large glossy black to dark brown curved horn with two small pointed tines on the inner curve near the tip, smooth and beetle-like",
      "where": "arising from the center of the forehead between and just in front of the ears, curving upward and forward"
    },
    {
      "part": "ears",
      "looks_like": "two small rounded ears covered in thick brown fur",
      "where": "on top of the head behind the horn, one slightly behind the other in profile"
    },
    {
      "part": "legs",
      "looks_like": "four thick columnar legs covered in long shaggy dark brown fur, with glossy dark brown joint plates around the upper and lower joints",
      "where": "two forelegs under the chest/shoulder and two hindlegs under the hips, extending from body to ground"
    },
    {
      "part": "feet",
      "looks_like": "four broad bear paws with thick pads and five long curved light tan claws on each",
      "where": "at the bottom of each leg in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "short stubby tail covered in shaggy brown fur",
      "where": "protruding from the rear left end of the body above the hindlegs"
    },
    {
      "part": "plates",
      "looks_like": "multiple glossy chitinous plates in dark reddish-brown and black: a large irregular shield with a pointed top over the shoulder, a large elongated ridged wing-cover with a black-edged suture on the mid-flank, and several smaller triangular, oval and irregular plates on the back, rump, throat and around the leg joints; with a row of small dark oval holes along the lower flank",
      "where": "embedded in the fur across the dorsal back, shoulder, mid-side, rump, throat, chest and encircling the leg joints"
    },
    {
      "part": "markings",
      "looks_like": "lighter cream-white fur contrasting with the darker brown, and a row of small dark oval spiracles",
      "where": "cream fur on the underbelly, lower chest and throat; spiracles in a horizontal line along the lower side between the front and hind legs"
    }
  ],
  "attached_objects": [],
  "animals": [
    "bear",
    "beetle"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
